#include "Studio.h"
namespace pulse {
using namespace juce;
const HarmonyGuide& Studio::activeHarmonyGuide()const{return harmonyPresetGuide&&harmonyToolActive()&&noteToolCurrent()?*harmonyPresetGuide:harmonyGuide;}
HarmonyPresetKind Studio::currentHarmonyPresetKind()const{return noteToolOptions.mode==NoteToolMode::buildProgression?HarmonyPresetKind::progression:noteToolOptions.mode==NoteToolMode::buildChord?HarmonyPresetKind::chord:HarmonyPresetKind::fitScale;}
HarmonyPreset Studio::captureHarmonyPreset(const String& id,const String& name)const{HarmonyPreset p;p.id=id;p.name=name;p.kind=currentHarmonyPresetKind();p.guide=activeHarmonyGuide();p.direction=scaleFitDirection;p.chord=chordOptions;p.chord.beat=0;p.progression=progressionOptions;p.progression.beat=0;return p;}
bool Studio::applyHarmonyPreset(const HarmonyPreset& p,uint64_t expected,uint64_t serial){
    if(!harmonyContext(expected,serial)){status="Harmony target or settings changed. Reopen Presets.";return false;}
    if(p.kind!=currentHarmonyPresetKind()){status="Choose a preset for the current harmony tool.";return false;}auto valid=validateHarmonyPreset(p);if(valid.failed()){status=valid.getErrorMessage();return false;}
    harmonyPresetGuide=p.guide;if(p.kind==HarmonyPresetKind::chord){double beat=chordOptions.beat;chordOptions=p.chord;chordOptions.beat=beat;pianoLow=-1;}else if(p.kind==HarmonyPresetKind::progression){double beat=progressionOptions.beat;progressionOptions=p.progression;progressionOptions.beat=beat;pianoLow=-1;}else scaleFitDirection=p.direction;
    selectedHarmonyPreset[(size_t)p.kind]=p.id;++harmonyToolSerial;refreshNoteToolPreview();status="Loaded "+p.name+(noteToolValid?". Preview only; Apply changes notes.":". Adjust settings for this target before Apply.");repaint();return true;
}
bool Studio::storeHarmonyPreset(const HarmonyPreset& p,bool replace,const String& token){
    if(recording||recorder.isActive()){status="Finish the take before saving harmony presets.";return false;}auto valid=putHarmonyPreset(root.getChildFile("data/harmony-presets.json"),p,replace,token);if(valid.failed()){status=valid.getErrorMessage();return false;}selectedHarmonyPreset[(size_t)p.kind]=p.id;status="Saved local "+harmonyPresetKindName(p.kind)+" preset: "+p.name+". Song and default guide are unchanged.";repaint();return true;
}
bool Studio::deleteHarmonyPreset(const String& id,const String& token){
    if(recording||recorder.isActive()){status="Finish the take before deleting harmony presets.";return false;}auto valid=removeHarmonyPreset(root.getChildFile("data/harmony-presets.json"),id,token);if(valid.failed()){status=valid.getErrorMessage();return false;}for(auto& selected:selectedHarmonyPreset)if(selected==id)selected.clear();status="Harmony preset deleted. Current preview and song are unchanged.";repaint();return true;
}
void Studio::nameHarmonyPreset(HarmonyPreset p,bool rename,const String& token){
    auto* dialog=new AlertWindow(rename?"Rename harmony preset":"Save harmony preset",harmonyPresetKindName(p.kind)+" settings only. Use a unique name for this tool (1-64 characters). Insertion beat stays with the target; preset guide stays temporary until explicitly saved in Scale settings.",MessageBoxIconType::NoIcon,this);dialog->addTextEditor("name",p.name);dialog->addButton(rename?"Rename":"Save",1,KeyPress(KeyPress::returnKey));dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);auto expected=revision,serial=harmonyToolSerial;
    dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,p,rename,token,expected,serial](int choice)mutable{if(!safe||choice!=1)return;if(!safe->harmonyContext(expected,serial)){safe->status="Harmony source or settings changed. Reopen Save preset.";return;}p.name=dialog->getTextEditorContents("name").trim();safe->storeHarmonyPreset(p,rename,token);}),true);
}
void Studio::showHarmonyPresets(){
    if(!harmonyContext(revision,harmonyToolSerial)){status="Start a current harmony preview before choosing presets.";return;}
    auto kind=currentHarmonyPresetKind();auto file=root.getChildFile("data/harmony-presets.json");auto token=harmonyPresetToken(file);std::vector<HarmonyPreset> rows;auto loaded=loadHarmonyPresets(file,rows);if(loaded.failed())status=loaded.getErrorMessage();auto factories=factoryHarmonyPresets(kind);std::vector<HarmonyPreset> personal;for(const auto& p:rows)if(p.kind==kind)personal.push_back(p);std::sort(personal.begin(),personal.end(),[](const auto& a,const auto& b){return a.name.compareIgnoreCase(b.name)<0;});auto id=selectedHarmonyPreset[(size_t)kind];auto found=std::find_if(personal.begin(),personal.end(),[&](const auto& p){return p.id==id;});bool selected=found!=personal.end();HarmonyPreset current=selected?*found:captureHarmonyPreset(Uuid().toString(),"Harmony settings");
    PopupMenu menu,factoryMenu,personalMenu;menu.addSectionHeader(harmonyPresetKindName(kind)+" presets");for(int i=0;i<(int)factories.size();++i)factoryMenu.addItem(100+i,factories[(size_t)i].name,true,id==factories[(size_t)i].id);menu.addSubMenu("Factory",factoryMenu);
    if(personal.empty())personalMenu.addItem(999,"No personal presets yet",false);else for(int start=0;start<(int)personal.size();start+=24){PopupMenu page;for(int i=start;i<jmin(start+24,(int)personal.size());++i)page.addItem(1000+i,personal[(size_t)i].name,true,id==personal[(size_t)i].id);if(personal.size()<=24)personalMenu=page;else personalMenu.addSubMenu(String(start+1)+" - "+String(jmin(start+24,(int)personal.size())),page);}menu.addSubMenu("Personal",personalMenu);
    if(kind==HarmonyPresetKind::progression)menu.addItem(8,"Degree examples (keep key and timing)...");menu.addSeparator();menu.addItem(1,"Save settings as new preset...",loaded.wasOk()&&rows.size()<maxHarmonyPresets);menu.addItem(2,"Update selected personal preset",loaded.wasOk()&&selected);menu.addItem(3,"Rename selected personal preset...",loaded.wasOk()&&selected);menu.addItem(4,"Delete selected personal preset...",loaded.wasOk()&&selected);menu.addSeparator();menu.addItem(5,"Import one preset...",loaded.wasOk()&&rows.size()<maxHarmonyPresets);menu.addItem(6,"Export current settings...");if(loaded.failed())menu.addItem(7,"Personal library unavailable - see status",false);auto safe=Component::SafePointer<Studio>(this);auto expected=revision,serial=harmonyToolSerial;
    menu.showMenuAsync(menuOptions(notePresetsOpen),[safe,kind,factories,personal,current,selected,token,expected,serial](int result){
        if(!safe||!result)return;if(!safe->harmonyContext(expected,serial)){safe->status="Harmony source or settings changed. Reopen Presets.";return;}
        if(result>=100&&result<100+(int)factories.size()){safe->applyHarmonyPreset(factories[(size_t)(result-100)],expected,serial);return;}
        if(result==8&&kind==HarmonyPresetKind::progression){safe->showProgressionExamples();return;}
        auto library=safe->root.getChildFile("data/harmony-presets.json");if(result!=6&&harmonyPresetToken(library)!=token){safe->status="Harmony library changed. Reopen Presets.";return;}
        if(result>=1000&&result<1000+(int)personal.size()){safe->applyHarmonyPreset(personal[(size_t)(result-1000)],expected,serial);return;}
        if(result==1){safe->nameHarmonyPreset(safe->captureHarmonyPreset(Uuid().toString(),""),false,token);return;}if(result==2&&selected){safe->storeHarmonyPreset(safe->captureHarmonyPreset(current.id,current.name),true,token);return;}if(result==3&&selected){safe->nameHarmonyPreset(current,true,token);return;}
        if(result==4&&selected){auto* dialog=new AlertWindow("Delete harmony preset","Delete \""+current.name+"\" from the local library? The current preview and song stay intact.",MessageBoxIconType::QuestionIcon,safe.getComponent());dialog->addButton("Delete",1);dialog->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));dialog->enterModalState(true,ModalCallbackFunction::create([safe,current,token,expected,serial](int choice){if(safe&&choice==1){if(!safe->harmonyContext(expected,serial)){safe->status="Harmony context changed. Reopen Delete preset.";return;}safe->deleteHarmonyPreset(current.id,token);}}),true);return;}
        if(result==5||result==6){bool exporting=result==6;auto captured=safe->captureHarmonyPreset(Uuid().toString(),selected?current.name:"Harmony settings");if(exporting){auto valid=validateHarmonyPreset(captured);if(valid.failed()){safe->status=valid.getErrorMessage();return;}}
            safe->chooser=std::make_unique<FileChooser>(exporting?"Export harmony settings":"Import one harmony preset",exporting?safe->root.getChildFile("harmony-preset.pulseharmony"):safe->root,"*.pulseharmony",true);int flags=exporting?FileBrowserComponent::saveMode|FileBrowserComponent::canSelectFiles|FileBrowserComponent::warnAboutOverwriting:FileBrowserComponent::openMode|FileBrowserComponent::canSelectFiles;
            safe->chooser->launchAsync(flags,[safe,exporting,captured,token,expected,serial](const FileChooser& chooser){if(!safe)return;auto file=chooser.getResult();if(file==File())return;if(!safe->harmonyContext(expected,serial)){safe->status="Harmony context changed. Reopen preset exchange.";return;}if(exporting){auto valid=saveHarmonyPresets(file,{captured},harmonyPresetToken(file));safe->status=valid.wasOk()?"Harmony settings exported: "+file.getFileName():valid.getErrorMessage();return;}std::vector<HarmonyPreset> imported;auto valid=loadHarmonyPresets(file,imported);if(valid.failed()||imported.size()!=1){safe->status=valid.failed()?valid.getErrorMessage():"Choose a single exported harmony preset.";return;}auto p=imported.front();p.id=Uuid().toString();safe->nameHarmonyPreset(p,false,token);});
        }
    });
}
}
